const setDownloadsFetched = `-- name: SetDownloadsFetched :execrows
UPDATE downloads SET updated_at = ?1, fetched_at = ?1
WHERE device_id = ?2 AND account_id = ?3 AND fetched_at IS NULL
  AND state IN ('ready', 'evicted') AND id IN (/*SLICE:ids*/?)
`

type SetDownloadsFetchedParams struct {
	Now       int64
	DeviceID  string
	AccountID int64
	Ids       []string
}

// The device reports complete files (sync): the server copy is removed 24 h later (AN-20).
func (q *Queries) SetDownloadsFetched(ctx context.Context, arg SetDownloadsFetchedParams) (int64, error) {
	query := setDownloadsFetched
	var queryParams []interface{}
	queryParams = append(queryParams, arg.Now)
	queryParams = append(queryParams, arg.DeviceID)
	queryParams = append(queryParams, arg.AccountID)
	if len(arg.Ids) > 0 {
		for _, v := range arg.Ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(arg.Ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	result, err := q.db.ExecContext(ctx, query, queryParams...)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

